"""Actual browser navigation/layout checks; no strategic accuracy assertions."""
import os,subprocess,json
from pathlib import Path

BASIC = r'''const fs=require('fs'),assert=require('node:assert/strict'),{chromium}=require('playwright');
(async()=>{const b=await chromium.launch({executablePath:process.env.CHROMIUM_EXECUTABLE||'/usr/bin/chromium',args:['--no-sandbox']}),errors=[],results=[];
for(const [device,width,height]of [['desktop',1600,1000],['mobile',390,844]]){
 const p=await b.newPage({viewport:{width,height},hasTouch:true,reducedMotion:'reduce'});p.on('pageerror',e=>errors.push(e.stack));await p.goto(process.env.ROOT+'/lol-coach/loading.html');await p.locator('#analyze:enabled').waitFor();await p.locator('#example-0').click();await p.locator('#analyze').click();
 assert.equal(await p.locator('.plan-area-card').count(),3,'three area entry cards');assert(await p.locator('.plan-detail').isHidden());assert.equal(await p.locator('.plan-team-row .plan-pick').count(),10);await p.locator('#loading-results').scrollIntoViewIfNeeded();await p.screenshot({path:process.env.OUT+'/'+device+'-summary.png'});
 await p.locator('[data-plan-area=lane]').click();assert(await p.locator('.plan-detail').isVisible());assert.equal(await p.locator('[data-action-summary=lane] [data-action-kind]').count(),5);assert.equal(await p.locator('.plan-perspectives section').count(),2);assert(await p.locator('.coach-action-text').first().evaluate(e=>e.getBoundingClientRect().width>180),'action text has readable width');await p.screenshot({path:process.env.OUT+'/'+device+'-lane.png'});
 const url=p.url();await p.reload();await p.locator('.plan-detail').waitFor();assert.equal(await p.locator('.plan-detail').getAttribute('data-detail-area'),'lane');await p.locator('[data-coach-focus=close-detail]').click();await p.locator('.plan-detail').waitFor({state:'hidden'});await p.locator('[data-plan-area=fight]').click();await p.goBack();assert(await p.locator('.plan-detail').isHidden());await p.goForward();assert.equal(await p.locator('.plan-detail').getAttribute('data-detail-area'),'fight');
 await p.locator('[data-coach-focus=close-detail]').click();await p.locator('[data-plan-edit]').click();await p.locator('#own-champion').selectOption('Ahri');await p.locator('#own-position').selectOption('MID');await p.locator('#analyze').click();assert.equal(await p.locator('.plan-master').getAttribute('data-own'),'Ahri');assert.match(await p.locator('.plan-hero-art').getAttribute('src'),/Ahri/);await p.screenshot({path:process.env.OUT+'/'+device+'-ahri.png'});await p.locator('[data-plan-area=lane]').click();assert.match(await p.locator('.plan-perspectives').innerText(),/제드/);assert(!((await p.locator('.plan-perspectives').innerText()).includes('케이틀린·럭스')));
 assert(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));results.push({device,url,caitlynAndAhri:true,backForwardRefresh:true});await p.close();}
 assert.deepEqual(errors,[]);fs.writeFileSync(process.env.OUT+'/result.json',JSON.stringify({results,errors},null,2));await b.close();})().catch(e=>{console.error(e);process.exit(1)});
'''
EDGES = r'''const fs=require('fs'),assert=require('node:assert/strict'),{chromium}=require('playwright');
(async()=>{const b=await chromium.launch({executablePath:process.env.CHROMIUM_EXECUTABLE||'/usr/bin/chromium',args:['--no-sandbox']}),errors=[],results=[],base=process.env.ROOT+'/lol-coach/';
const p=await b.newPage({viewport:{width:1440,height:1000},hasTouch:true,reducedMotion:'reduce'});p.on('pageerror',e=>errors.push(e.message));await p.goto(base+'loading.html');await p.locator('#analyze:enabled').waitFor();await p.locator('#example-0').click();await p.locator('#analyze').click();
await p.locator('[data-plan-area=lane]').focus();await p.keyboard.press('Enter');assert(await p.locator('.plan-detail').isVisible());await p.locator('[data-action-kind=TRADE]').click();assert(await p.locator('[data-action-detail=lane-methods]').isVisible());assert(await p.locator('[data-action-detail=lane-methods]').evaluate(e=>e===document.activeElement));
await p.locator('[data-coach-focus=period-LEVEL2]').click();await p.locator('#loading-coach details[id$="-conditions"]').evaluate(e=>e.open=true);await p.locator('[data-coach-focus=condition-enemy_key]').selectOption('SPENT');await p.waitForFunction(()=>document.querySelector('#loading-coach').getAttribute('aria-busy')==='false');const first=await p.locator('.plan-area-cards').textContent(),h=p.url();assert(h.includes('LEVEL2'));await p.reload();await p.locator('.plan-detail').waitFor();assert.equal(await p.locator('.plan-layout').getAttribute('data-period'),'LEVEL2');assert.equal(await p.locator('.plan-area-cards').textContent(),first);assert.equal(await p.locator('[data-coach-focus=condition-enemy_key]').inputValue(),'SPENT');
await p.locator('[data-coach-focus=tab-fight]').click();await p.locator('details[id$="-retained-fight"]').evaluate(e=>e.open=true);const f=p.locator('.formation-explorer');await f.locator('[data-formation-control=FLANK_ISOLATE]').click();await f.locator('[data-formation-control=step-2]').click();await p.locator('[data-coach-focus=close-detail]').click();await p.locator('.plan-detail').waitFor({state:'hidden'});await p.locator('[data-plan-area=fight]').click();await p.locator('details[id$="-retained-fight"]').evaluate(e=>e.open=true);assert.equal(await f.locator('.formation-arena').first().getAttribute('data-formation-step'),'2');assert.equal(await f.locator('.formation-arena').first().getAttribute('data-formation-scene'),'FLANK_ISOLATE');await f.locator('[data-formation-zoom]').click();await p.keyboard.press('Escape');assert(await f.locator('dialog').isHidden());
const shared=p.url();const direct=await b.newPage({viewport:{width:390,height:844}});await direct.goto(shared);await direct.locator('.plan-detail').waitFor();assert.equal(await direct.locator('.plan-detail').getAttribute('data-detail-area'),'fight');await direct.locator('[data-coach-focus=close-detail]').click();await direct.locator('.plan-detail').waitFor({state:'hidden'});assert.match(direct.url(),/plan=/);await direct.close();
await p.locator('[data-coach-focus=close-detail]').click();await p.locator('.plan-detail').waitFor({state:'hidden'});for(const [w,h] of [[1280,853],[1024,768],[768,1024],[320,740]]){await p.setViewportSize({width:w,height:h});await p.locator('[data-plan-area=lane]').click();assert.equal(await p.locator('.plan-master').isVisible(),w>=1280);assert(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));assert(await p.locator('.coach-action-text').first().evaluate(e=>parseFloat(getComputedStyle(e).fontSize)>=15));await p.screenshot({path:process.env.OUT+'/detail-'+w+'.png'});await p.locator('[data-coach-focus=close-detail]').click();await p.locator('.plan-detail').waitFor({state:'hidden'});assert.equal(await p.evaluate(()=>document.activeElement?.dataset.planArea),'lane');}
await p.setViewportSize({width:1440,height:1000});await p.evaluate(()=>document.documentElement.style.fontSize='200%');await p.locator('[data-plan-area=lane]').click();assert(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));await p.screenshot({path:process.env.OUT+'/zoom-200.png'});await p.evaluate(()=>document.documentElement.style.fontSize='');
await p.locator('details[id$="-retained-common"]').evaluate(e=>e.open=true);await p.locator('[data-coach-focus=legacy-open]').click();assert(await p.locator('#loading-legacy-details').evaluate(e=>e.open));assert(await p.locator('#loading-lane').isVisible());
await p.locator('#loading-legacy-details').evaluate(e=>e.open=true);await p.locator('#risk-OPPORTUNITY').check();assert.equal(await p.evaluate(()=>LoadingPresentation.decode(location.hash).input.preferences.risk),'OPPORTUNITY','legacy preference must share route');
await p.locator('[data-coach-focus=close-detail]').click();await p.locator('.plan-detail').waitFor({state:'hidden'});await p.locator('[data-plan-area=lane]').click();await p.locator('#input-panel').evaluate(e=>e.open=true);await p.locator('#pick-ALLY-0').fill('Malphite');assert(await p.locator('#loading-results').isHidden());await p.goBack();await p.locator('.plan-master').waitFor();assert.match(await p.locator('.plan-team-row.allies').innerText(),/오른/);assert(!((await p.locator('.plan-team-row.allies').innerText()).includes('말파이트')));
await p.goto(base+'loading.html#plan=broken');await p.locator('#analyze:enabled').waitFor();assert.match(await p.locator('#loading-message').innerText(),/링크/);assert(await p.locator('#loading-results').isHidden());
await p.route('**/home-assets/Caitlyn.jpg',r=>r.abort());await p.goto(base+'loading.html');await p.locator('#analyze:enabled').waitFor();await p.locator('#example-0').click();await p.locator('#analyze').click();await p.locator('.plan-hero.art-unavailable').waitFor();await p.locator('[data-plan-area=lane]').click();assert(await p.locator('.plan-detail').isVisible());await p.unroute('**/home-assets/Caitlyn.jpg');
await p.route('**/loading-data.json',r=>r.fulfill({status:503,body:'unavailable'}));await p.goto(base+'loading.html');await p.locator('#loading-message.is-error').waitFor();assert(await p.locator('#analyze').isDisabled());assert(await p.locator('#loading-form').isVisible());await p.unroute('**/loading-data.json');
assert.deepEqual(errors,[]);fs.writeFileSync(process.env.OUT+'/edge-result.json',JSON.stringify({keyboard:true,conditionsAndPeriodRestored:true,directLink:true,formationSelectionPreserved:true,viewports:[1440,1280,1024,768,320],zoom200:true,invalidAndAssetAndDataFailure:true,errors},null,2));await b.close();})().catch(e=>{console.error(e);process.exit(1)});
'''

def run(base,out,env):
    out=Path(out)/'presentation';out.mkdir(exist_ok=True)
    for name,source in [('basic',BASIC),('edge',EDGES)]:
        probe=out/(name+'.cjs');probe.write_text(source)
        r=subprocess.run(['node',str(probe)],env={**env,'ROOT':base,'OUT':str(out)},text=True,capture_output=True,timeout=180)
        (out/(name+'.log')).write_text(r.stdout+r.stderr)
        if r.returncode:raise RuntimeError(name+' browser check failed: '+r.stderr[-2500:])
    return {'basic':json.loads((out/'result.json').read_text()),'edges':json.loads((out/'edge-result.json').read_text())}
